"""Key pairwise jobs by frozen evidence and reject changed model/evidence before dispatch."""
from pathlib import Path
p = Path('backend/app/phase3_api.py')
s = p.read_text(encoding='utf-8')
s = s.replace("        return {'job_id': enqueue(db, 'pairwise', body.model_dump())}", "        from .feedback import ReviewSample\n        from .offline_evaluation import blind_packet, JUDGE_PROMPT_VERSION, JUDGE_SCHEMA_VERSION\n        from .evaluation_replay import digest\n        with db.session() as session:\n            samples = [session.get(ReviewSample, sid) for sid in body.sample_ids]\n            if any(sample is None for sample in samples):\n                raise HTTPException(404, 'Unknown sample')\n            hashes = [digest(blind_packet(sample)) for sample in samples]\n        return {'job_id': enqueue(db, 'pairwise', {'parameters': body.model_dump(), 'evidence_hashes': hashes, 'model': provider.models['judge'], 'prompt_version': 'blind-pairwise-1', 'schema_version': JUDGE_SCHEMA_VERSION, 'rubric_version': 'hard-pass-relevance-0-3-1'})}")
p.write_text(s, encoding='utf-8')
p = Path('backend/app/offline_evaluation.py')
s = p.read_text(encoding='utf-8')
s = s.replace("                result = await audit_explanation(self.db, job.payload['cache_key'], self.provider)", "                from .explanations import ExplanationCache\n                with self.db.session() as session:\n                    explanation = session.get(ExplanationCache, job.payload['cache_key'])\n                    if explanation is None or digest(explanation.payload) != job.payload['source_hash'] or self.provider.models['judge'] != job.payload['model']:\n                        raise ValueError('Grounding evidence or model changed')\n                result = await audit_explanation(self.db, job.payload['cache_key'], self.provider)")
s = s.replace("                result = await evaluate_pair(self.db, provider=self.provider, **job.payload)", "                with self.db.session() as session:\n                    samples = [session.get(ReviewSample, sid) for sid in job.payload['parameters']['sample_ids']]\n                    if any(s is None for s in samples) or [digest(blind_packet(s)) for s in samples] != job.payload['evidence_hashes'] or self.provider.models['judge'] != job.payload['model']:\n                        raise ValueError('Pair evidence or model changed')\n                result = await evaluate_pair(self.db, provider=self.provider, **job.payload['parameters'])")
s = s.replace("                result = await improve(self.db, job.payload, self.provider)", "                if self.provider.models['improvement'] != job.payload.get('model', self.provider.models['improvement']):\n                    raise ValueError('Improvement model changed')\n                result = await improve(self.db, job.payload, self.provider)")
p.write_text(s, encoding='utf-8')
